=<html><head><meta charset="utf-8"><style>
  body { font-family: Arial, sans-serif; margin: 0; padding: 40px; color: #222; }
  .header { border-bottom: 3px solid #2563eb; padding-bottom: 16px; margin-bottom: 24px; }
  .store { font-size: 22px; font-weight: bold; color: #1e40af; }
  .meta { font-size: 12px; color: #555; margin-top: 4px; }
  .inv-title { font-size: 28px; font-weight: bold; color: #111; margin: 20px 0 4px; }
  .inv-no { color: #2563eb; font-size: 14px; margin-bottom: 20px; }
  table { width: 100%; border-collapse: collapse; margin: 16px 0; font-size: 13px; }
  th { background: #2563eb; color: #fff; padding: 10px; text-align: left; }
  td { padding: 9px 10px; border-bottom: 1px solid #e5e7eb; }
  .num { text-align: right; }
  .totals { margin-top: 16px; text-align: right; font-size: 14px; }
  .totals .grand { font-size: 20px; font-weight: bold; color: #1e40af; border-top: 2px solid #2563eb; padding-top: 8px; margin-top: 8px; }
  .footer { margin-top: 40px; padding-top: 16px; border-top: 1px solid #ddd; font-size: 11px; color: #666; text-align: center; }
</style></head><body>
  <div class="header">
    <div class="store">{{ $json.store_name }}</div>
    <div class="meta">{{ $json.store_address }}</div>
  </div>
  <div class="inv-title">INVOICE</div>
  <div class="inv-no">{{ $json.invoice_no }}</div>
  <div style="font-size:13px; margin-bottom:16px;">
    <b>Billed to:</b> {{ $json.buyer_name }}<br>
    <b>Date:</b> {{ $json.date }}<br>
    <b>Payment method:</b> {{ $json.payment_method }}
  </div>
  <table>
    <tr><th>Item</th><th class="num">Qty</th><th class="num">Price</th><th class="num">Amount</th></tr>
    {{ JSON.parse($json.items).map(i => `<tr><td>${i.name}</td><td class="num">${i.qty}</td><td class="num">Rp ${Number(i.price).toLocaleString('id-ID')}</td><td class="num">Rp ${(i.qty*i.price).toLocaleString('id-ID')}</td></tr>`).join('') }}
  </table>
  <div class="totals">
    Subtotal: Rp {{ Number($json.subtotal).toLocaleString('id-ID') }}<br>
    Shipping: Rp {{ Number($json.shipping).toLocaleString('id-ID') }}<br>
    <div class="grand">TOTAL: Rp {{ Number($json.total).toLocaleString('id-ID') }}</div>
  </div>
  <div class="footer">Thank you for shopping at {{ $json.store_name }}.<br>This invoice was generated automatically by the system.</div>
</body></html>
